```cpp
#include <iostream>
#include <algorithm>

using namespace std;

int main() {
    int m1_rows, m1_cols, m2_rows, m2_cols;

    cout << "Enter the dimensions of the first matrix (rows cols): ";
    cin >> m1_rows >> m1_cols;

    int matrix1[m1_rows][m1_cols];

    cout << "Enter the elements of the first matrix:" << endl;
    for (int I = 0; I < m1_rows; i++) {
        for (int j = 0; j < m1_cols; j++) {
            cin >> matrix1[i][j];
        }
    }

    cout << "Enter the dimensions of the second matrix (rows cols): ";
    cin >> m2_rows >> m2_cols;

    int matrix2[m2_rows][m2_cols];

    cout << "Enter the elements of the second matrix:" << endl;
    for (int I = 0; I < m2_rows; i++) {
        for (int j = 0; j < m2_cols; j++) {
            cin >> matrix2[i][j];
        }
    }

    // Find the minimum number of rows and columns between the two matrices
    int min_rows = min(m1_rows, m2_rows);
    int min_cols = min(m1_cols, m2_cols);

    // Initialize the result matrix with all elements set to -1
    int result_matrix[min_rows][min_cols];
    for (int I = 0; I < min_rows; i++) {
        for (int j = 0; j < min_cols; j++) {
            result_matrix[i][j] = -1;
        }
    }

    // Traverse both matrices and find common elements
    int common_count = 0;
    for (int I = 0; I < min_rows; i++) {
        for (int j = 0; j < min_cols; j++) {
            if (matrix1[i][j] == matrix2[i][j] && matrix1[i][j] != -1) {
                result_matrix[common_count][0] = matrix1[i][j];
                result_matrix[common_count][1] = i;
                result_matrix[common_count][2] = j;
                common_count++;
            }
        }
    }

    // Print the result matrix
    cout << "Common elements:" << endl;
    if (common_count == 0) {
        cout << "No common elements found." << endl;
    } else {
        for (int I = 0; I < common_count; i++) {
            cout << result_matrix[i][0] << " ";
        }
        cout << endl;

        cout << "Index of common elements in first matrix:" << endl;
        for (int I = 0; I < common_count; i++) {
            cout << result_matrix[i][1] << " " << result_matrix[i][2] << endl;
        }
    }

    return 0;
}
```

Este programa toma dos matrices como input y encuentra los elementos comunes entre ellas. El algoritmo funciona en tres pasos:

1. Compara cada elemento en la primera matriz con el elemento correspondiente en la segunda matriz. Si ambos son iguales y no son -1 (porque los valores -1 son utilizados para indicar que el elemento no es común), se agrega ese elemento a una matriz de resultados, junto con su índice en la primera matriz.

2. Encuentra el mínimo número de filas y columnas entre las dos matrices. Esto se hace para que la matriz de resultados tenga el tamaño mínimo posible.

3. Imprime los elementos comunes encontrados en la matriz de resultados, junto con sus índices en la primera matriz.

